-- Seed competency taxonomy from CSV (docs/taxonomy_cn/Competency_Taxonomy_CN.csv).
-- Bilingual: name/category = English, name_zh/category_zh = Simplified Chinese.
-- Populates competency_taxonomy_seed and syncs to company_capabilities_ref.
-- Generated by scripts/generate-taxonomy-seeds.mjs.

-- Full rebuild: IDs are regenerated from the CSV, so clear the working ref
-- table too (cascades to company_capabilities). Company selections are
-- preserved across a reseed by scripts/reseed-taxonomy-with-remap.mjs.
DELETE FROM public.company_capabilities;
DELETE FROM public.company_capabilities_ref;
DELETE FROM public.competency_taxonomy_seed;

-- L1 (Level1_Domain): category = domain itself

-- L2 (Level2_CapabilityGroup): category = parent L1 domain

-- L3 (Level3_Competency): category = NULL

-- Sync canonical seed into the working ref table used by companies.
SELECT id, name, name_zh, category, category_zh, parent_id, is_active FROM public.competency_taxonomy_seed
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, name_zh = EXCLUDED.name_zh, category = EXCLUDED.category, category_zh = EXCLUDED.category_zh, parent_id = EXCLUDED.parent_id, is_active = EXCLUDED.is_active;

